// HasVerificationToken applies the HasEdge predicate on the "verification_token" edge.
func HasVerificationToken() predicate.SecurityEmailDelivery {
	return predicate.SecurityEmailDelivery(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, VerificationTokenTable, VerificationTokenColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasVerificationTokenWith applies the HasEdge predicate on the "verification_token" edge with a given conditions (other predicates).
func HasVerificationTokenWith(preds ...predicate.RecoveryContactVerificationToken) predicate.SecurityEmailDelivery {
	return predicate.SecurityEmailDelivery(func(s *sql.Selector) {
		step := newVerificationTokenStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

